import json, os, subprocess

root = os.path.expanduser("~/.claude/jobs")
rows = []
for j in sorted(os.listdir(root)):
    p = os.path.join(root, j)
    try:
        d = json.load(open(os.path.join(p, "state.json")))
    except Exception:
        d = {}
    tmp = os.path.join(p, "tmp")
    size = 0
    if os.path.isdir(tmp):
        out = subprocess.run(["du", "-sk", tmp], capture_output=True, text=True).stdout.split()
        size = int(out[0]) if out else 0
    rows.append((size, j, d.get("state"), d.get("name"), d.get("cwd"), (d.get("updatedAt") or "")[:10]))
