import json, sys

d = json.load(sys.stdin)
sets = d["propSets"]


def names_of(ref):
    if isinstance(ref, list):
        out = []
        for r in ref:
            out += list(sets.get(r, {}))
        return out
    if isinstance(ref, dict):
        return list(ref)
    return list(sets.get(ref, {}))


for name, comp in d["components"].items():
    rows = names_of(comp["props"])
    notable = names_of(comp.get("notableInherited", {}))
    layers = [(l["typeName"], l.get("totalProps"), len(l.get("used", []))) for l in comp.get("inheritance", [])]
    have = [n for n in ("className", "style", "ref") if n in rows or n in notable]
    print(name, "rows:", len(rows), "notable:", len(notable), "has className/style/ref:", have)
    print("  layers:", layers)

