#[test]
fn a_source_only_a_react_type_reaches_collapses_like_any_other_large_source() {
    // `CSSProperties` is React's and extends csstype's `Properties`, which is made of interfaces of hundreds of members.
    // Only the checker reads them. They reach the component whole through React's type, so the large ones are layers as
    // they are when a project type extends them directly, not hundreds of rows ("never hide on silence" holds only
    // where the walk could not prove the reach).
    let files = [(
        "Styled.tsx",
        "import type { CSSProperties } from 'react';\n\
         export interface StyleProps extends CSSProperties { own?: string }\n\
         export function Styled(props: StyleProps) { return null; }\n"
            .to_owned(),
    )];
    let (_dir, [_, checker]) = both_lanes(&files, CollapseInheritedProps::Dependencies);
    let styled = &checker.components["Styled"];
    let large = ["StandardLonghandProperties", "VendorLonghandProperties"];
    let listed: Vec<&str> = styled
        .props
        .values()
        .filter_map(|prop| prop.parent.as_ref().map(|parent| parent.name.as_str()))
        .filter(|parent| large.contains(parent))
        .collect();
    assert_eq!(listed, Vec::<&str>::new(), "a large csstype source is listed prop by prop");
    for source in large {
        let layer = styled.inheritance.iter().find(|layer| layer.type_name == source);
        assert!(layer.is_some_and(|layer| layer.members.len() > 200), "{source} is a layer of names: {:?}", styled.inheritance);
    }
    assert!(styled.props.contains_key("own"), "the props type's own member is a row");
}
