import json, re, subprocess, sys

main_bin, new_bin, src, runs = sys.argv[1], sys.argv[2], sys.argv[3], int(sys.argv[4])
args = ["extract", "--src", src, "--quiet", "--no-cache", "--load-dependencies", "--json"]


def run(binary):
    p = subprocess.run(["/usr/bin/time", "-l", binary, *args], capture_output=True, text=True)
    real = re.search(r"([\d.]+)\s+real", p.stderr)
    rss = re.search(r"(\d+)\s+maximum resident", p.stderr)
    return p.stdout, float(real.group(1)), int(rss.group(1)) / 1048576


def rows(d):
    out = {}
    for name, comp in d["components"].items():
        names = set()
        for ref in comp["props"]:
            names |= set(d["propSets"].get(ref, {}))
        out[name] = len(names)
    return out


res = {"main": [], "new": []}
outs = {}
for i in range(runs):
    for label, binary in (("main", main_bin), ("new", new_bin)):
        out, real, rss = run(binary)
        res[label].append((real, rss))
        outs[label] = out
for label in res:
    print(label, " ".join(f"{r:.1f}s/{m:.0f}MiB" for r, m in res[label]))
a, b = json.loads(outs["main"]), json.loads(outs["new"])
ra, rb = rows(a), rows(b)
changed = [(k, ra[k], rb[k]) for k in ra if k in rb and ra[k] != rb[k]]
print("components", len(ra), len(rb), "rows differ in", len(changed))
tot_a, tot_b = sum(ra.values()), sum(rb.values())
print("total rows", tot_a, "->", tot_b)
for k, x, y in sorted(changed, key=lambda t: t[2] - t[1])[:8]:
    print(" ", k[:40], x, "->", y)

