import json, subprocess, sys

bins = {"a": sys.argv[1], "b": sys.argv[2], "a2": sys.argv[1]}
src = sys.argv[3]
args = ["extract", "--src", src, "--quiet", "--no-cache", "--load-dependencies", "--json"]
data = {k: json.loads(subprocess.run([v, *args], capture_output=True, text=True).stdout) for k, v in bins.items()}


def names(d, comp):
    s = set()
    for ref in d["components"][comp]["props"]:
        s |= set(d["propSets"].get(ref, {}))
    return s


def parents(d, comp):
    out = {}
    for ref in d["components"][comp]["props"]:
        for n, pid in d["propSets"].get(ref, {}).items():
            p = d["props"][pid].get("parent")
            out[n] = p["name"] if p else None
    return out


for comp in sys.argv[4:]:
    base, new, again = (names(data[k], comp) for k in ("a", "b", "a2"))
    print(comp, "main-vs-main differs:", sorted(base ^ again), "| new adds:", sorted(new - base), "drops:", sorted(base - new))
    print("   parents of added:", {n: parents(data["b"], comp).get(n) for n in new - base})

