import type { HTMLAttributes } from 'react';
declare function useThing(props: object): { id: string };
export function Handed(props: HTMLAttributes<HTMLDivElement> & { own?: string }) {
  const thing = useThing(props);
  return <div id={thing.id} />;
}
export function Reads(props: HTMLAttributes<HTMLDivElement> & { own?: string }) {
  return <div className={props.className} />;
}

